-- =====================================================================
-- 0036 — صفحتا التعريف: «عن المنصة» موجزة، و«عن المبادرة» دليل عرضٍ للجهات
--   المختصة بما استجد، وخدماتٌ بباركود، ورابط اطّلاع خاص بلا رقم سرّي
--   (ملاحظتا ١٣٥ و١٣٦). ولا يُذكر في الصفحتين شيء مالي؛ فذلك شأن داخلي.
-- =====================================================================

-- ---------------------------------------------------------------------
-- رابط الاطّلاع الخاص: يُرسَل للجهة فيفتح الصفحة بلا رقم سرّي، ويُبطَل بإنشاء غيره
-- ---------------------------------------------------------------------
alter table public.page_content add column if not exists share_token text;
create unique index if not exists page_content_share_token
  on public.page_content (share_token) where share_token is not null;
comment on column public.page_content.share_token is 'رابط اطّلاع خاص بلا رقم سرّي (ملاحظة ١٣٦)';

create or replace function public.open_page(p_key text, p_code text default null)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v_row public.page_content;
begin
  select * into v_row from public.page_content where key = p_key;
  if v_row.key is null then raise exception 'الصفحة غير موجودة'; end if;

  -- أعضاء المنصة المفعّلون يرونها بلا رمز
  if exists (select 1 from public.profiles p where p.id = auth.uid() and p.status = 'active') then
    return v_row.content;
  end if;

  -- رابط الاطّلاع الخاص (ملاحظة ١٣٦)
  if v_row.share_token is not null and p_code is not null
     and trim(p_code) = v_row.share_token then
    return v_row.content;
  end if;

  if v_row.code_hash is null then return v_row.content; end if;

  if p_code is null or length(trim(p_code)) = 0 then
    raise exception 'REQUIRE_CODE' using errcode = '42501';
  end if;
  if crypt(trim(p_code), v_row.code_hash) <> v_row.code_hash then
    raise exception 'رمز الاطّلاع غير صحيح' using errcode = '42501';
  end if;
  return v_row.content;
end $$;

grant execute on function public.open_page(text, text) to anon, authenticated;

-- إنشاء رابط اطّلاع جديد (يُبطِل ما قبله) — لمدير المشروع
create or replace function public.new_page_link(p_key text)
returns text language plpgsql security definer set search_path = public as $$
declare v_token text;
begin
  if not public.is_manager() then raise exception 'رابط الاطّلاع لمدير المشروع' using errcode = '42501'; end if;
  v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  update public.page_content
     set share_token = v_token, updated_at = now(), updated_by = auth.uid()
   where key = p_key;
  if not found then raise exception 'الصفحة غير موجودة'; end if;
  return v_token;
end $$;

create or replace function public.clear_page_link(p_key text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_manager() then raise exception 'رابط الاطّلاع لمدير المشروع' using errcode = '42501'; end if;
  update public.page_content set share_token = null, updated_at = now(), updated_by = auth.uid()
   where key = p_key;
end $$;

grant execute on function public.new_page_link(text) to authenticated;
grant execute on function public.clear_page_link(text) to authenticated;

-- ---------------------------------------------------------------------
-- المحتوى المحدَّث
-- ---------------------------------------------------------------------
insert into public.page_content (key, content, updated_at) values ('about', '{"badge": "مبادرة من إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين", "h1": "منصة إدارة ترجمة خطب الحرمين الشريفين", "lead": "من الأصل العربي إلى الترجمة المعتمدة؛ بيئة عمل موحدة، ومراجعات متخصصة، ومسؤوليات واضحة.", "note": "", "vision": "أن تصل رسالة الحرمين الشريفين إلى العالم بلغاته، بترجمة موثوقة، وفي الوقت المناسب، وبما يليق بمكانتهما.", "mission": "إدارة أعمال ترجمة خطب الحرمين الشريفين ودروسهما ومواد الهيئة في منصة رقمية موحدة، تجمع الكفاءات المتخصصة، وتضبط مراحل العمل والصلاحيات، وتحفظ سرية المحتوى، وتوثق المسؤوليات.", "stats": [["50", "لغة ترجمة"], ["13", "لغة رئيسية"], ["6", "مراحل لكل لغة"]], "goals": [], "roles": [], "stages": [["الترجمة", "المترجم", "إعداد الترجمة داخل المنصة، استنادًا إلى الأصل العربي، ووفق القالب المعتمد للهيئة."], ["المراجعة الشرعية", "المراجع الشرعي", "التحقق من سلامة المعاني الشرعية ودقة نقل الآيات والأحاديث والمصطلحات والأدلة."], ["المراجعة اللغوية", "المراجع اللغوي", "مراجعة سلامة اللغة والأسلوب والقواعد، ووضوح المعنى في اللغة المستهدفة."], ["التحرير والإخراج", "المحرر", "ضبط العناوين والتنسيق والصياغة التحريرية، وتهيئة المادة في صورتها النهائية."], ["المراجعة التنسيقية والاستلام", "المنسق", "التحقق من اكتمال المتطلبات والمراجعات، ومعالجة الملاحظات، وارتباط العمل بالنسخة الصحيحة من الأصل."], ["الاعتماد النهائي", "مدير المشروع", "اعتماد النسخة النهائية وإجازة تسليمها للنشر وفق الإجراءات والصلاحيات المقررة."]], "sections": [["brief", "عن المنصة", [["p", "منصة رسمية واحدة تُدار بها ترجمة خطب المسجد الحرام والمسجد النبوي ودروسهما ومواد الهيئة، من استلام الأصل العربي إلى اعتماد الترجمة وترقيمها وتجهيزها للنشر."], ["p", "تجمع المنصة المادة وترجماتها وملاحظاتها ومواعيدها في مكان واحد؛ فلكل مادة نسخة مرجعية، ولكل مرحلة مسؤول، ولكل إجراء سجل."], ["cards", [["مسار لكل لغة", "تُسند لغات المادة، ولكل لغة مسار مستقل بمواعيده ومسؤوليه."], ["مراجعة متخصصة", "مراجعة شرعية ولغوية وتحرير قبل الاعتماد النهائي."], ["سرية محفوظة", "المواد غير المنشورة مقيدة التداول، والعمل داخل بيئة المنصة."], ["أرشيف مرقَّم وكشوف", "لكل عمل معتمد رقم توثيق يُطبع عليه، وأرشيف يُتصفَّح بأنواعه وتُصدَّر كشوفه."]]], ["diagram", "cycle"], ["stagenames"]]]]}'::jsonb, now())
on conflict (key) do update set content = excluded.content, updated_at = now();

insert into public.page_content (key, content, updated_at) values ('initiative', '{"badge": "الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي — مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين", "h1": "مبادرة أتمتة الترجمة في الحرمين الشريفين", "lead": "دليل عرضٍ للجهات المختصة: ما المبادرة، وما الذي أُنجز منها، وكيف تُدار أعمال الترجمة اليوم في منصة رسمية واحدة.", "note": "يصف هذا الدليل ما هو قائم ومطبَّق في المنصة، عدا قسم «آفاق التطوير» فهو توجهات تخضع للدراسة والاعتماد.", "vision": "أن تصل رسالة الحرمين الشريفين إلى العالم بلغاته، بترجمة موثوقة، وفي الوقت المناسب، وبما يليق بمكانتهما.", "mission": "أتمتة أعمال ترجمة خطب الحرمين الشريفين ودروسهما ومواد الهيئة في منصة رقمية موحدة، تجمع الكفاءات المتخصصة، وتضبط مراحل العمل والصلاحيات والمواعيد، وتحفظ سرية المحتوى، وتوثق كل إجراء.", "stats": [["50", "لغة ترجمة في المنصة"], ["13", "لغة رئيسية"], ["6", "مراحل لكل لغة"], ["رقم توثيق", "لكل عمل معتمد"], ["يوميًّا", "نسخ احتياطي مشفّر"]], "goals": ["أتمتة دورة العمل كاملة: من إدخال الأصل إلى اعتماد الترجمة وأرشفتها، بلا تداول ملفات خارج المنصة.", "تعزيز جودة الترجمة: بتنظيم المراجعة الشرعية واللغوية، وضبط إجراءات اعتماد المخرجات.", "رفع كفاءة الإنجاز: بتوحيد الإسناد والمتابعة، وتحديد المواعيد، وتقليل الوقت المستغرق في تداول الملفات واستكمال الملاحظات.", "حماية المحتوى والبيانات: بتنظيم الوصول إلى المواد والوثائق، وتقييد تداولها بحسب الأدوار والصلاحيات.", "توثيق الأعمال وفهرستها: بمنح كل عمل معتمد رقم توثيق ثابت، يُبنى عليه أرشيف منظم وكشوف إنجاز دقيقة.", "دعم التوسع واستمرارية العمل: بتهيئة المنصة لإضافة لغات جديدة، وتحويل إجراءات العمل إلى ممارسة مؤسسية موثقة."], "stages": [["الترجمة", "المترجم", "إعداد الترجمة داخل المنصة، استنادًا إلى الأصل العربي، ووفق القالب المعتمد للهيئة."], ["المراجعة الشرعية", "المراجع الشرعي", "التحقق من سلامة المعاني الشرعية ودقة نقل الآيات والأحاديث والمصطلحات."], ["المراجعة اللغوية", "المراجع اللغوي", "مراجعة سلامة اللغة والأسلوب والقواعد، ووضوح المعنى في اللغة المستهدفة."], ["التحرير والإخراج", "المحرر", "ضبط العناوين والتنسيق والصياغة التحريرية، وتهيئة المادة في صورتها النهائية."], ["المراجعة التنسيقية والاستلام", "المنسق", "التحقق من اكتمال المتطلبات والمراجعات، ومعالجة الملاحظات."], ["الاعتماد النهائي", "مدير المشروع", "اعتماد النسخة النهائية وإجازة تسليمها للنشر وفق الصلاحيات المقررة."]], "roles": [["مدير المشروع", ["يتولى الإشراف العام على المنصة، واعتماد مسارات العمل والصلاحيات، وإدارة الأدوار الإدارية، واعتماد المخرجات النهائية، والإشراف على الأرشفة والاسترجاع وفق الصلاحيات المحددة."]], ["المنسق", ["يتولى إدخال المواد، وتحديد اللغات، وإسناد المهام، وضبط المواعيد، ومتابعة الإنجاز، واستلام الأعمال وإعادتها عند الحاجة بملاحظات واضحة.", "كما يتولى مراجعة طلبات الانضمام واستكمال إجراءات تفعيل الحسابات ضمن صلاحياته، وإرسال المراسلات ومتابعة الإقرار بالاطلاع عليها، وجدولة ورديات الإرشاد المكاني."]], ["المترجم والمراجع والمحرر", ["ينفذ كل عضو المهام المسندة إليه وفق اختصاصه واللغات المعتمدة له، ويعمل داخل المنصة على المواد المتاحة لحسابه، مع توثيق ملاحظاته ورفع المخرجات المطلوبة في المواعيد المحددة.", "ويتيح الحساب للعضو إدارة بياناته الشخصية، والاطلاع على تكليفاته ومراسلاته وبطاقة عمله بعد اعتمادها."]], ["المرشد المكاني", ["يتولى إرشاد قاصدي الحرمين الشريفين ميدانيًّا وفق الورديات المجدولة له، ويسجّل حضوره وانصرافه من حسابه في المنصة بالتوقيت المحلي."]]], "sections": [["initiative", "المبادرة", [["p", "مبادرة أتمتة الترجمة في الحرمين الشريفين مبادرة رقمية طوّرتها إدارة مشروع خادم الحرمين الشريفين لترجمة خطب الحرمين الشريفين؛ لنقل أعمال الترجمة من التنسيق اليدوي وتداول الملفات والرسائل المتفرقة، إلى منصة رسمية واحدة تُدار فيها الأعمال وتُوثَّق إجراءاتها وتُحفظ مخرجاتها."], ["p", "وتقوم المبادرة على ثلاثة أركان: بيئة عمل موحدة تجمع المادة الأصلية وترجماتها ومراجعاتها ومواعيدها؛ وضبطٌ للصلاحيات والسرية يحمي المحتوى قبل نشره؛ وتوثيقٌ لكل إجراء يُرجع إليه عند المتابعة والتقييم."], ["p", "وقد اكتملت اليوم دورة العمل في المنصة من استلام الأصل إلى اعتماد الترجمة وترقيمها وأرشفتها واستخراج كشوف الإنجاز منها."]]], ["vision", "الرؤية والرسالة", [["vision"]]], ["goals", "الأهداف", [["goals"]]], ["scope", "نطاق العمل والتغطية اللغوية", [["p", "تشمل أعمال المنصة خطب الجمعة والعيدين وعرفة والاستسقاء والكسوف، والدروس العلمية، والكتب والمطويات والمنشورات والإعلانات والتوجيهات، وفق نطاق الأعمال المسندة إلى المشروع."], ["p", "وتُصنَّف المواد بحسب نوعها وجهتها وتاريخها؛ فتُنسب الخطب والدروس إلى المسجد الحرام أو المسجد النبوي، وتُدرج المواد الأخرى ضمن التصنيفات المناسبة لها، بما يسهل إسنادها ومتابعتها والرجوع إليها."], ["diagram", "languages"], ["p", "تضم قائمة المنصة خمسين لغة ترجمة، من بينها ثلاث عشرة لغة رئيسية يمكن اختيارها ضمن مجموعة واحدة عند الإسناد. وتتيح إدارة اللغات إضافة لغات جديدة أو تعطيلها بحسب حاجة العمل وتوافر الكفاءات، دون الحاجة إلى تعديل برمجي في كل مرة."], ["p", "ويرتبط إسناد المهام باللغات المعتمدة لكل عضو؛ فلا تُسند إليه مهمة بلغة لم يُعتمد للعمل فيها. وتبقى اللغة العربية لغة الأصل الذي تُعد عنه الترجمات، ولا تدخل ضمن عدد لغات الترجمة."]]], ["how", "كيف تعمل المنصة؟", [["p", "تبدأ دورة العمل بإدخال المادة الأصلية وبياناتها، ثم تحديد اللغات المطلوبة، وإسناد المسؤوليات، وضبط مواعيد التسليم. ويُنشأ لكل لغة مسار مستقل يمكن متابعة تقدمه وحالته."], ["diagram", "cycle"], ["p", "يتكون المسار القياسي من ست مراحل:"], ["stages"], ["p", "وتُعرض لوحة متابعة تُظهر الأعمال الجارية وتوزّعها على المراحل، ويُفتح كل مؤشر منها على تفصيله؛ فيُعرف في أي مرحلة وقف كل عمل ومن المسؤول عنه."], ["p", "ويُتاح للمراجعين تعديل النص ضمن نطاق اختصاصهم، مع توثيق الملاحظات والتعديلات. ولا تُعاد المادة إلى مرحلة سابقة إلا بسبب مكتوب يوضح المطلوب، كما يُعاد أي تعديل لاحق يؤثر في المعنى إلى المراجعة المختصة قبل تجديد الاعتماد."], ["callout", "اعتماد الترجمة لا يعني إتاحتها للجمهور تلقائيًا؛ إذ يظل النشر مرتبطًا بالموعد والإذن المحددين من الجهة المختصة."]]], ["quality", "ضبط الجودة والمواعيد وإدارة التعديلات", [["p", "يرتبط كل تكليف بموعد تسليم محدد، وتُعرض للمسؤول عن المرحلة المدة المتبقية لإنجازها، مع مؤشرات واضحة عند تجاوز الموعد. ولا تُغلق المرحلة إلا بعد استيفاء متطلباتها، بما في ذلك رفع التسجيل الصوتي حين يكون جزءًا من التكليف."], ["p", "ويُعدّ النص المترجَم داخل المنصة على كليشة الهيئة بمقاسها المعتمد، مع علامات إرشادية تُبيّن حدود الصفحة وهوامشها ولا تظهر في الطباعة؛ فيخرج العمل مضبوط التنسيق في صورته النهائية."], ["p", "ويجمع تقييم الأداء بين جودة العمل، والالتزام بالمواعيد، والاستجابة للملاحظات، بالاستفادة من مؤشرات المتابعة الآلية والتقييم المهني للإدارة. وتُراعى أسباب الإعادة عند التقييم، بحيث يُميَّز بين الملاحظات المتعلقة بجودة العمل والتعديلات الناتجة عن تحديث الأصل."], ["h3", "التعامل مع تحديث الأصل العربي"], ["p", "تراعي المنصة احتمال تعديل النص العربي بعد بدء العمل عليه. ويُوثَّق التحديث من خلال تحديد مواضع التعديل، أو إرفاق نسخة محدثة من الأصل مع حفظ النسخة السابقة، أو إضافة ملاحظة توضح التغيير المطلوب."], ["p", "ويحدد المنسق اللغات المتأثرة بالتعديل والمرحلة التي تعود إليها كل ترجمة، مع تمييز النسخة السارية من الأصل؛ فتظل كل ترجمة مرتبطة بأصل معلوم، ويُحدّ من الالتباس بين النسخ."]]], ["docs", "ترقيم التوثيق والفهرسة", [["p", "يُمنح كل عمل عند اكتمال مساره واعتماده رقمَ توثيق ثابتًا لا يتغير بعد ذلك، يُطبع على العمل في نسخه كلها ويُحفظ به في الأرشيف؛ ليكون مرجعًا دقيقًا للفهرسة والبحث والمطابقة مستقبلًا."], ["docno", [["H48", "السنة الهجرية", "الحرف H وسنتان من التاريخ الهجري"], ["EN", "رمز اللغة", "رمز اللغة المترجَم إليها"], ["1", "النطاق", "0 عام · 1 تابع لمكة المكرمة · 2 تابع للمدينة المنورة"], ["2", "نوع العمل", "1 جمعة · 2 عرفة · 3 أضحى · 4 فطر · 5 استسقاء · 6 كسوف · 7 درس علمي · 8 كتاب · 9 مطوية · 0 منشورات وتوجيهات وإعلانات"], ["0042", "تسلسل العمل", "أربعة أرقام تتجدد مع كل سنة هجرية داخل النوع نفسه"]]], ["p", "ويُطبع مع الرقم رمزُ تحقّق (QR) يفتح صفحة تبيّن وصف العمل وتاريخ اعتماده دون كشف محتواه؛ فيُتحقق من أي نسخة مطبوعة بمسح الرمز."], ["p", "وخانة نوع العمل قابلة للتوسع إلى الحروف عند إضافة أنواع جديدة، فيتسع الترقيم لآلاف الأعمال دون تغيير في بنيته."]]], ["archive", "الأرشيف وكشوف الإنجاز", [["p", "تُحفظ الأعمال المعتمدة وترجماتها وتسجيلاتها الصوتية في أرشيف منظم يُدخَل ببطاقات أنواع الأعمال: الخطب والدروس والكتب والمطويات والمنشورات والتوجيهات والإعلانات؛ وداخل الخطب بطاقات بأنواعها: الجمعة وعرفة والعيدين والاستسقاء والكسوف."], ["p", "وفي كل مستوى بحثٌ وفلترة باللغة والجهة والمدة ورقم التوثيق، وتصديرٌ للكشف بصيغ Excel وWord وPDF على كليشة الهيئة، بشهر أو سنة أو مدة محددة؛ فيُستخرج تقرير إنجاز المشروع خلال المدة المطلوبة جاهزًا للطباعة والتسليم."]]], ["team", "فريق العمل والأدوار والصلاحيات", [["roles"], ["h3", "الانضمام وتأهيل الأعضاء"], ["p", "يبدأ الانضمام بتقديم طلب تسجيل ومراجعة البيانات والمؤهلات، والتحقق من الكفاءة في اللغة والدور المطلوب وفق إجراءات المشروع. ولا يترتب على تقديم الطلب تفعيل الحساب أو منح الصلاحيات تلقائيًا."], ["h3", "ميثاق العمل"], ["p", "يوقّع كل عضو ميثاق العمل إلكترونيًّا قبل مباشرة مهامه، وفيه ما يلزمه تجاه المواد والمواعيد والسرية. ويُحفظ توقيعه بتاريخه، ولا يستلم تكليفًا قبل التوقيع؛ وتتابع الإدارة من وقّع ومن لم يوقّع في كشف مستقل."]]], ["field", "الإرشاد المكاني والورديات", [["p", "إلى جانب فرق الترجمة، تُدار في المنصة ورديات المرشدين المكانيين في الحرمين الشريفين: تُجدوَل الوردية بيومها ووقتها وموقعها، ويُسنَد لها مسؤول ومعه أعضاؤها."], ["p", "ويسجّل المرشد حضوره وانصرافه من حسابه بالتوقيت المحلي، فتُحتسب مدة الوردية وما وقع فيها من تأخر، ويُستخرج تقرير شهري بالحضور والانصراف للإدارة."]]], ["security", "السرية وحماية المحتوى والبيانات", [["p", "تُعامل المواد غير المنشورة بوصفها مواد مقيدة التداول، ولا تُتاح إلا للمخولين بالعمل عليها، وفي حدود ما تتطلبه مهامهم. ويُوثَّق إقرار الأعضاء بالسرية إلكترونيًا قبل استلام التكليفات."], ["diagram", "security"], ["p", "ويُعرض الأصل العربي داخل المنصة مع علامة مائية تتضمن معرّف المستخدم وتاريخ الاطلاع، وتُقيَّد إمكانات النسخ والتنزيل وفق الصلاحيات. وتهدف هذه الإجراءات إلى الحد من التداول غير المصرح به وتعزيز إمكانية تتبع الاطلاع على المادة."], ["p", "وتُطبق ضوابط الوصول على مستوى النظام وقاعدة البيانات، وليس في واجهة الاستخدام وحدها؛ بما يحصر وصول كل عضو إلى الأعمال والبيانات المصرح له بها. ويُلزَم أصحاب الحسابات الإدارية بالتحقق بخطوتين عند الدخول."], ["p", "وتُستخدم التنبيهات البريدية لإبلاغ الأعضاء بالتكليفات والمستجدات، مع إبقاء المحتوى المقيد داخل بيئة العمل. ولا يُسمح بمشاركة المواد غير المنشورة مع خدمات ترجمة أو أدوات ذكاء اصطناعي خارجية غير معتمدة."], ["callout", "إتاحة الترجمة للنشر لا تعني إتاحة بيانات العاملين عليها؛ إذ تظل بيانات الأعضاء ووثائقهم محمية وفق صلاحيات الاطلاع المقررة."]]], ["continuity", "النسخ الاحتياطي واستمرارية العمل", [["p", "تُنشأ نسخ احتياطية يومية تشمل قاعدة البيانات والملفات، وتُشفَّر قبل حفظها في مخزنها المخصص، مع تقييد الوصول إليها وتنظيم مدد الاحتفاظ بها."], ["p", "وتشمل إجراءات التحقق من موثوقية النسخ اختبار استعادتها والتأكد من إمكان استرجاع البيانات والملفات بصورة متكاملة، إلى جانب متابعة نجاح عمليات النسخ ومعالجة أي خلل يظهر فيها."], ["p", "ويُراعى في تنظيم استمرارية العمل توثيق إجراءات التشغيل والاستعادة، وتحديد المسؤوليات وبدائلها؛ بما يدعم استعادة الخدمة والمحافظة على سير الأعمال."]]], ["governance", "الحوكمة والتوثيق والتواصل المؤسسي", [["p", "يرتبط بكل مادة سجل زمني يوضح إنشاءها، وإسناد مهامها، وانتقالها بين المراحل، والملاحظات والتعديلات التي أُجريت عليها، وأسباب إعادتها، وقرارات اعتمادها."], ["p", "وتُحمى سجلات الإجراءات من التعديل غير المصرح به، وتُستخدم مرجعًا للمتابعة والتقييم والمراجعة. كما تخضع عمليات حذف الأعمال واسترجاعها لصلاحيات وإجراءات محددة، مع توثيق القرارات المرتبطة بها."], ["p", "وتوفر المنصة قناة داخلية لإرسال التعاميم والتوجيهات والدعوات، نصًا أو بمرفقات، إلى جميع الأعضاء أو فئات محددة أو أشخاص بأعيانهم. ويُوثَّق اطلاع العضو وتوقيعه بالعلم، بما يتيح للإدارة متابعة الاستجابة دون الاعتماد على المراسلات المتفرقة."], ["p", "وتدعم الإشعارات متابعة سير العمل، من إبلاغ العضو بالمهمة وموعدها إلى تنبيه الإدارة باكتمال مراحل اللغة واستعدادها للإجراء التالي."]]], ["outputs", "مخرجات المنصة", [["cards", [["ترجمات معتمدة وجاهزة للتسليم", "نسخ نهائية لكل لغة على القالب الرسمي المعتمد للهيئة، قابلة للطباعة والتصدير بصيغتي Word وPDF، مع ضبط التنسيق وترقيم الصفحات ورقم التوثيق."], ["أرشيف منظم للمواد والترجمات", "حفظ المواد المعتمدة وترجماتها وتسجيلاتها الصوتية، وتصنيفها بحسب نوع المادة وتاريخها وجهتها ولغتها؛ بما يسهل البحث والرجوع إليها وإعادة الاستفادة منها."], ["كشوف إنجاز قابلة للتخصيص", "كشوف بالأعمال المنجزة خلال شهر أو سنة أو مدة محددة، بصيغ Excel وWord وPDF على الكليشة، مع إجمالياتها وتوزيعها على الأنواع واللغات."], ["كشوف إدارية للفريق", "إعداد كشوف بيانات الفريق وتصديرها، مع اختيار الأعضاء والحقول المطلوبة، وإضافة عنوان للكشف وخانات للتوقيع أو الحضور عند الحاجة، وفق صلاحيات الاطلاع."], ["بطاقات عمل تعريفية", "إعداد بطاقات تتضمن صورة العضو وبياناته ورقم عضويته ولغاته، وإتاحتها في حسابه بعد اعتمادها، وفق التصميم والضوابط المعتمدة للمشروع."], ["تقارير الحضور والورديات", "جدول ورديات الإرشاد المكاني، وتقرير شهري بالحضور والانصراف وما وقع من تأخر، للمتابعة الإدارية."]]]]], ["services", "خدمات المبادرة", [["p", "خدمات المبادرة متاحة اليوم على الشبكة؛ ويفتح كلَّ خدمة رمزُها أدناه بمسحه بكاميرا الجوال، أو بالضغط عليه مباشرة:"], ["qrlinks", [["البث المباشر لخطب الحرمين الشريفين", "https://haramainsermons.com/", "أحدث خطب الجمعة والعيدين مترجمةً بلغات العالم"], ["أرشيف الخطب والمجالس العلمية", "https://haramainsermons.com/?tab=archive", "الخطب السابقة والدروس، بحثًا وتصفّحًا باللغة"], ["خطبة يوم عرفة", "https://haramainsermons.com/arafah", "صفحة مستقلة لخطبة عرفة بلغاتها"], ["التحقق من رقم التوثيق", "https://haramainsermons.com/verify", "يبيّن وصف العمل المعتمد وتاريخ اعتماده من رقمه المطبوع"], ["منصة العمل — لفريق المشروع", "https://platform.haramainsermons.com/", "بيئة العمل الداخلية، الدخول لأعضاء الفريق المعتمدين"]]]]], ["future", "آفاق التطوير", [["p", "تمثل المسارات الآتية توجهات مستقبلية تخضع للدراسة والاعتماد، ولا تُعرض بوصفها وظائف منفذة ضمن النسخة الحالية:"], ["ul", ["التوسع اللغوي والأرشيفي: إضافة لغات وفق الحاجة وتوافر الكفاءات، وضم الترجمات السابقة إلى الأرشيف.", "التكامل مع قنوات النشر: ربط المخرجات بالقنوات الرسمية، مع المحافظة على ضوابط الاعتماد والإذن بالنشر.", "تطوير خدمات المستفيدين: دراسة توفير تطبيق للجوال ييسر الوصول إلى الترجمات والمحتوى المنشور.", "فهرسة موسّعة: البناء على رقم التوثيق في بحث متقدم يجمع آلاف الأعمال بأنواعها ولغاتها وتواريخها.", "لوحات المؤشرات: عرض معدلات الإنجاز والالتزام بالمواعيد وأسباب الإعادة والتغطية اللغوية؛ لدعم القرار.", "التكامل الصوتي: دراسة ربط التسجيلات بقنوات البث والنشر، وفق متطلبات المراجعة والتشغيل والتزامن."]]]], ["closing", "عمل مؤسسي موثَّق لخدمة رسالة الحرمين الشريفين", [["p", "تجمع المبادرة بين الكفاءة البشرية والتنظيم الرقمي؛ لتكون المادة محفوظة، والمهمة محددة، والمراجعة موثقة، والنسخة النهائية معتمدة ومرقَّمة. ومن خلال هذه البيئة الموحدة، تدعم إدارة المشروع جودة الترجمة واستمرارية العمل والتوسع في خدمة المستفيدين، بما يليق برسالة الحرمين الشريفين ومكانتهما."]]]]}'::jsonb, now())
